    const nodes = [];
    const numNodes = 2500;

    for (let i = 0; i < numNodes; i++) {
      nodes.push({
        x: random() * canvas.width,
        y: random() * canvas.height,
        type: random() > 0.96 ? 'hub' : 'standard'
      });
    }

    ctx.fillStyle = '#0A0D15';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

