        let maxDist = n1.type === 'hub' ? 80000 : 20000;

        if (dist < maxDist) {
          ctx.beginPath();
          ctx.moveTo(n1.x, n1.y);
          ctx.quadraticCurveTo(n1.x, n2.y, n2.x, n2.y);

          let opacity = 1 - (dist / maxDist);
          opacity *= 0.35;

          if (n1.type === 'hub') {
            ctx.strokeStyle = `rgba(0, 229, 255, ${opacity * 1.5})`;
          } else {
            ctx.strokeStyle = `rgba(130, 146, 166, ${opacity})`;
          }

          ctx.stroke();
          connected++;
        }
        if (connected >= connections) break;
      }

      ctx.beginPath();
      ctx.arc(n1.x, n1.y, n1.type === 'hub' ? 3 : 1, 0, Math.PI * 2);
      ctx.fillStyle = n1.type === 'hub' ? '#00FFB2' : 'rgba(255,255,255,0.4)';
      ctx.fill();
    }

    let gradient = ctx.createRadialGradient(canvas.width*0.7, canvas.height*0.4, 100, canvas.width*0.7, canvas.height*0.4, 1800);
    gradient.addColorStop(0, 'rgba(0, 229, 255, 0.12)');
    gradient.addColorStop(1, 'transparent');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

